#include <vector>

//==========================================
// RING MODULE (HOA 3: circular doubly linked list)
// Every node has a next AND a previous pointer, and the last node points back to the first one,
// so moving "next" or "previous" never reaches an end, it just goes round and round.
// The list keeps a CURSOR (the item that is shown now), like the song that is playing in Playlist.h.
//
// Used in this project for the Featured games carousel (browse.h builds the ring, store.h shows it).
//==========================================

template <typename T>
class RingList {
private:
    struct Node {
        T value;
        Node* next;
        Node* prev;
    };
    Node* head;         // the first item (the carousel starts here)
    Node* cursor;       // the item shown now, nullptr only when the list is empty
    int count;

    // make this ring a copy of another one, the cursor ends on the same position
//--- RingList::copyFrom ---------------------------------------------------------------------------
// What    : Copies all items of another object, keeping the same order.
// Used by : RingList::operator=, RingList::RingList
//--------------------------------------------------------------------------------------------------
    void copyFrom(const RingList& other) {
        if (other.head == nullptr) return;
        Node* cur = other.head;
        int cursorPlace = 0;
        for (int i = 0; i < other.count; i++, cur = cur->next) {
            pushBack(cur->value);
            if (cur == other.cursor) cursorPlace = i;
        }
        cursor = head;
        for (int i = 0; i < cursorPlace; i++) cursor = cursor->next;
    }

public:
//--- RingList::RingList ---------------------------------------------------------------------------
// What    : Creates an empty RingList.
// Used by : doFeatured (screens.h), doShowcase (screens.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    RingList() : head(nullptr), cursor(nullptr), count(0) {}

//--- RingList::~RingList --------------------------------------------------------------------------
// What    : Frees all memory of the RingList (rule of three).
// Used by : runs by itself when the object goes out of scope or is deleted
//--------------------------------------------------------------------------------------------------
    ~RingList() { clear(); }

//--- RingList::RingList ---------------------------------------------------------------------------
// What    : Copy constructor: makes a separate copy of all items (part of the rule of three).
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    RingList(const RingList& other) : head(nullptr), cursor(nullptr), count(0) { copyFrom(other); }

//--- RingList::operator= --------------------------------------------------------------------------
// What    : Copy assignment: replaces the items with a copy of another RingList. The `if (this !=
//           &other)` check makes x = x safe.
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    RingList& operator=(const RingList& other) {
        if (this != &other) {
            clear();
            copyFrom(other);
        }
        return *this;
    }

//--- RingList::empty ------------------------------------------------------------------------------
// What    : Tells if there are no items.
// Returns : true when empty
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool empty() const { return head == nullptr; }
//--- RingList::size -------------------------------------------------------------------------------
// What    : Number of items.
// Returns : the count
// Used by : doFeatured (screens.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    int size() const { return count; }

    // adds a new item just before the head, which is the END of the ring
//--- RingList::pushBack ---------------------------------------------------------------------------
// What    : Adds an item at the end of the ring (just before the head).
// Used by : doFeatured (screens.h), doShowcase (screens.h), RingList::copyFrom,
//           RingList::pushFront, tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    void pushBack(const T& value) {
        Node* node = new Node{value, nullptr, nullptr};
        if (head == nullptr) {
            node->next = node;
            node->prev = node;
            head = node;
            cursor = node;
        } else {
            Node* tail = head->prev;
            node->next = head;
            node->prev = tail;
            tail->next = node;
            head->prev = node;
        }
        count++;
    }

    // adds a new item as the new head, which is the START of the ring
//--- RingList::pushFront --------------------------------------------------------------------------
// What    : Adds an item as the new head of the ring.
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    void pushFront(const T& value) {
        pushBack(value);
        head = head->prev;                  // the node that was just added becomes the head
    }

    // moves the cursor one place forward / backward. false when the ring is empty
//--- RingList::moveNext ---------------------------------------------------------------------------
// What    : Moves the cursor one place forward. After the last item it goes to the first.
// Returns : false when the ring is empty
// Used by : doFeatured (screens.h), doShowcase (screens.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool moveNext() {
        if (cursor == nullptr) return false;
        cursor = cursor->next;
        return true;
    }

//--- RingList::movePrev ---------------------------------------------------------------------------
// What    : Moves the cursor one place back. Before the first item it goes to the last.
// Returns : false when the ring is empty
// Used by : doFeatured (screens.h), doShowcase (screens.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool movePrev() {
        if (cursor == nullptr) return false;
        cursor = cursor->prev;
        return true;
    }

    // the item under the cursor. false when the ring is empty
//--- RingList::current ----------------------------------------------------------------------------
// What    : The item under the cursor.
// Returns : false when the ring is empty
// Used by : doFeatured (screens.h), doShowcase (screens.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool current(T& out) const {
        if (cursor == nullptr) return false;
        out = cursor->value;
        return true;
    }

    // place of the cursor counted from the head, 1 for the head itself. 0 when the ring is empty
//--- RingList::position ---------------------------------------------------------------------------
// What    : Place of the cursor counted from the head, starting at 1.
// Returns : the place, 0 when the ring is empty
// Used by : doFeatured (screens.h), tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    int position() const {
        if (cursor == nullptr) return 0;
        int place = 1;
        for (Node* cur = head; cur != cursor; cur = cur->next) place++;
        return place;
    }

    // removes the item under the cursor, the cursor moves to the next item. false when empty
//--- RingList::removeCurrent ----------------------------------------------------------------------
// What    : Removes the item under the cursor. The cursor moves to the next item.
// Returns : false when the ring is empty
// Used by : tests (tests/test_ds.cpp)
//--------------------------------------------------------------------------------------------------
    bool removeCurrent() {
        if (cursor == nullptr) return false;
        Node* old = cursor;
        if (count == 1) {
            head = nullptr;
            cursor = nullptr;
        } else {
            old->prev->next = old->next;
            old->next->prev = old->prev;
            if (head == old) head = old->next;
            cursor = old->next;
        }
        delete old;
        count--;
        return true;
    }

    // all items from the head forward, handy for printing the whole carousel
//--- RingList::toVector ---------------------------------------------------------------------------
// What    : Copies all items from the head forward into a vector.
// Returns : the items
// Used by : (nothing yet: not called from the program)
//--------------------------------------------------------------------------------------------------
    std::vector<T> toVector() const {
        std::vector<T> out;
        Node* cur = head;
        for (int i = 0; i < count; i++, cur = cur->next) out.push_back(cur->value);
        return out;
    }

//--- RingList::clear ------------------------------------------------------------------------------
// What    : Removes all items.
// Used by : RingList::operator=, RingList::~RingList
//--------------------------------------------------------------------------------------------------
    void clear() {
        if (head != nullptr) {
            head->prev->next = nullptr;      // cut the circle so the loop below can stop
            Node* cur = head;
            while (cur != nullptr) {
                Node* nxt = cur->next;
                delete cur;
                cur = nxt;
            }
        }
        head = nullptr;
        cursor = nullptr;
        count = 0;
    }
};

#endif //STEAM_RING_H
